        private void testMultiplication(BigInt a, BigInt b, BigInt result)
        {
            Assert.AreEqual(result, a * b);
            Assert.AreEqual(result, a.Multiply(b));
            Assert.AreEqual(result, b * a);
            Assert.AreEqual(result, b.Multiply(a));
        }

