        private void testDivisionModulo(BigInt a, BigInt b, BigInt resultDiv, BigInt resultMod)
        {
            Assert.AreEqual(resultDiv, a / b);
            Assert.AreEqual(resultDiv, a.Divide(b));
            Assert.AreEqual(resultMod, a % b);
            Assert.AreEqual(resultMod, a.Modulo(b));
            var qr = a.DivideModulo(b);
            Assert.AreEqual(resultDiv, qr.Quotient);
            Assert.AreEqual(resultMod, qr.Remainder);
        }

        private void testDivisionByZero(BigInt a, BigInt b)
        {
            Assert.Throws<DivideByZeroException>(() => { var _ = a / b; });
            Assert.Throws<DivideByZeroException>(() => { var _ = a.Divide(b); });
            Assert.Throws<DivideByZeroException>(() => { var _ = a % b; });
            Assert.Throws<DivideByZeroException>(() => { var _ = a.Modulo(b); });
            Assert.Throws<DivideByZeroException>(() => { var _ = a.DivideModulo(b); });
        }

