        private void testPositiveNegative(BigInt a, BigInt negative, int expectedSign)
        {
            Assert.AreEqual(a, +a);
            Assert.AreEqual(negative, -a);
            Assert.AreEqual(negative, a.Negative);
            Assert.AreEqual(expectedSign, a.Sign);
            Assert.AreEqual(expectedSign >= 0 ? a : negative, a.AbsoluteValue);
        }

