        private void testModPow(BigInt a, BigInt exp, BigInt mod, BigInt result)
        {
            if (mod.IsZero)
                Assert.Throws<DivideByZeroException>(() => a.ModPow(exp, mod));
            else
                Assert.AreEqual(result, a.ModPow(exp, mod));
        }

